import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Uptime and status page","description":"","frontmatter":{},"headers":[],"relativePath":"guide/uptime.md","filePath":"guide/uptime.md"}'),i={name:"guide/uptime.md"};function n(r,e,h,c,d,l){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="uptime-and-status-page" tabindex="-1">Uptime and status page <a class="header-anchor" href="#uptime-and-status-page" aria-label="Permalink to &quot;Uptime and status page&quot;">​</a></h1><p>Orbit checks every deployed web application once a minute, the way a visitor reaches it, and tells you when it stops answering. A public status page can show your users the same thing.</p><h2 id="check" tabindex="-1">The check <a class="header-anchor" href="#check" aria-label="Permalink to &quot;The check {#check}&quot;">​</a></h2><p>Every minute, Orbit sends a <code>GET</code> to each web application:</p><ul><li><strong>Address:</strong> its verified custom domain, or its generated address when it has none, over HTTPS once its certificate is issued.</li><li><strong>Path:</strong> the application&#39;s <a href="./applications#health-check">health check path</a>, changed under <strong>Settings → Health check</strong>, <code>/</code> by default. A saved change applies on the next uptime check. Redirects are not followed, so a <code>301</code> or <code>302</code> counts as an answer.</li><li><strong>Failure:</strong> a connection error, a TLS error, no answer within 10 seconds, or a <code>5xx</code> status. A <code>404</code> is an answer: the application is there.</li></ul><p>The application&#39;s overview shows its state, the share of checks that passed over the last 90 days, one bar per day, and the last failure.</p><p>Previews, workers and jobs are not checked.</p><h2 id="incidents" tabindex="-1">When it stops answering <a class="header-anchor" href="#incidents" aria-label="Permalink to &quot;When it stops answering {#incidents}&quot;">​</a></h2><ul><li><strong>Two failures in a row</strong>, a minute apart, mark the application down and open an <strong>unreachable</strong> incident with the address and the error. Channels that receive incidents are <a href="./notifications">notified</a> at once.</li><li><strong>A single failure</strong> keeps the application up and shows the error, so a lost request does not page anyone.</li><li><strong>The first success</strong> afterwards resolves the incident, which records how long the application was down.</li></ul><h2 id="vantage" tabindex="-1">Where the check runs <a class="header-anchor" href="#vantage" aria-label="Permalink to &quot;Where the check runs {#vantage}&quot;">​</a></h2><p>The check runs from the server Orbit runs on. It resolves the domain with public DNS, checks the certificate against the name, and goes through the router to the application. When the domain points at one of your servers, Orbit reaches that server at its private address, since some providers, Oracle Cloud among them, do not let a machine reach itself at its public address.</p><p>What it does not see:</p><ul><li>a provider&#39;s firewall in front of a server that blocks visitors but not Orbit;</li><li>an outage of the server Orbit runs on: Orbit stops with it, so nothing is checked until it is back. See <a href="./limits#control-plane">the main server</a>.</li></ul><p>Use an outside monitor too if you need either.</p><h2 id="status-page" tabindex="-1">Status page <a class="header-anchor" href="#status-page" aria-label="Permalink to &quot;Status page {#status-page}&quot;">​</a></h2><p>In <strong>Settings → Status page</strong>, choose a title, an address and the applications to show, then publish it. The page is public, with no sign-in, at <code>/status/&lt;address&gt;</code> on the console&#39;s address. It shows:</p><ul><li>whether everything is up, or which applications are down;</li><li>for each application you chose, its state and its uptime over the last 90 days, day by day;</li><li>with <strong>Show when they were down</strong>, every time an application was unreachable in those 90 days and for how long.</li></ul><p>Applications you did not choose never appear, nor do names of servers, projects or anything else. The page follows the visitor&#39;s language, English or Portuguese, refreshes itself every minute, and works in light and dark mode.</p><h3 id="status-domain" tabindex="-1">On your own domain <a class="header-anchor" href="#status-domain" aria-label="Permalink to &quot;On your own domain {#status-domain}&quot;">​</a></h3><p>Give the page a domain, such as <code>status.example.com</code>, and point it at the main server with an <code>A</code> record, the same as the console. Orbit then serves the page at the root of that domain, with a Let&#39;s Encrypt certificate, and nothing else: the console and the API do not answer there.</p><p>Each workspace has one status page. Addresses and domains are unique across workspaces.</p>',21)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
